WITH cleaned AS (SELECT *, LOWER(event_type) AS event_type_lower, CONCAT(event_type, ' ', page) AS event_type_page, COALESCE(page, 'DIRECT') AS resolved_page FROM web_events WHERE event_time > TO_TIMESTAMP('2023-07-01 05:00:00') AND page IS NOT NULL) SELECT id, session_id, event_type, page, event_time, duration_sec, event_type_page, MAX(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_duration_sec, MIN(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_duration_sec, AVG(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_6_prior FROM cleaned
